class span_buffer_adaptor {
private:
    std::span<const uint8_t> buffer_;
    size_t read_pos_ = 0;

public:
    using size_type = size_t;
    using offset_type = size_t;
    using value_type = uint8_t;
    using seeking = hexi::supported;
    using contiguous = hexi::supported;

    explicit span_buffer_adaptor(std::span<const uint8_t> buffer) : buffer_(buffer) {}

    size_type size() const { return buffer_.size(); }
    bool empty() const { return buffer_.empty(); }

    void read(void* dest, size_type size) {
        if (read_pos_ + size > buffer_.size()) {
            throw std::out_of_range("Read beyond buffer bounds");
        }
        std::memcpy(dest, buffer_.data() + read_pos_, size);
        read_pos_ += size;
