	template<is_iterable T>
	binary_stream_writer& operator<<(prefixed<T> adaptor) {
		const auto count = endian::native_to_little(static_cast<std::uint32_t>(adaptor->size()));
		write(&count, sizeof(count));
		write_container(adaptor.str);
