	 */
	auto write_ptr() {
		return buffer_.data() + write_;
	}

	/**
	 * @return Pointer to the data available for reading.
	 */
	auto data() const {
		return buffer_.data() + read_;
	}

	/**
	 * @return Pointer to the data available for reading.
	 */
	auto data() {
		return buffer_.data() + read_;
	}

	/**
	 * @return Pointer to the underlying storage.
	 */
	auto storage() const {
		return buffer_.data();
	}

	/**
	 * @return Pointer to the underlying storage.
	 */
	auto storage() {
		return buffer_.data();
	}

	/**
	 * @brief Advances the write cursor.
