We can't directly call the private `push()` and `pop()` methods, but we can observe their behavior through the public `allocate()` and `deallocate()` methods. Here's a complete implementation that demonstrates the free list management:

```cpp
#include "include/hexi/allocators/block_allocator.h"
#include <iostream>
#include <cassert>

// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    using namespace hexi;

    // Create a block allocator for integers
    block_allocator<int, element_count> allocator;

    std::cout << "=== Block Allocator Free List Demonstration ===\n";
    std::cout << "Allocator created with capacity for " << element_count << " elements\n\n";

    // Demonstrate allocation pattern (LIFO behavior)
    std::cout << "1. Allocating 3 objects:\n";
    int* obj1 = allocator.allocate(1);
    int* obj2 = allocator.allocate(2);
    int* obj3 = allocator.allocate(3);

    std::cout << "   Allocated objects at addresses: " 
              << obj1 << ", " << obj2 << ", " << obj3 << "\n";

    // Deallocate in reverse order (LIFO)
    std::cout << "\n2. Deallocating in reverse order (LIFO):\n";
    std::cout << "   Deallocating obj3 (" << obj3 << ") first\n";
    allocator.deallocate(obj3);

    std::cout << "   Deallocating obj2 (" << obj2 << ") next\n";
    allocator.deallocate(obj2);

    std::cout << "   Deallocating obj1 (" << obj1 << ") last\n";
    allocator.deallocate(obj1);

    // Now allocate again - should get the same blocks but in reverse order
    std::cout << "\n3. Allocating again - observing LIFO behavior:\n";
    int* obj4 = allocator.allocate(4);
    int* obj5 = allocator.allocate(5);
    int* obj6 = allocator.allocate(6);

    std::cout << "   New allocations: " << obj4 << ", " << obj5 << ", " << obj6 << "\n";

    // The free list works as a stack (LIFO):
    // After deallocating obj3, obj2, obj1 (in that order), the free list is:
    // head -> obj1 -> obj2 -> obj3
    // When we allocate again, we get: obj1, obj2, obj3 (in that order)
    // So obj4 should be at the same address as obj1
    // obj5 should be at the same address as obj2
    // obj6 should be at the same address as obj3

    std::cout << "\n4. Verifying LIFO free list behavior:\n";
    std::cout << "   obj4 (" << obj4 << ") should equal obj1's address\n";
    std::cout << "   obj5 (" << obj5 << ") should equal obj2's address\n";
    std::cout << "   obj6 (" << obj6 << ") should equal obj3's address\n";

    assert(obj4 == obj1 && "Free list LIFO behavior violated");
    assert(obj5 == obj2 && "Free list LIFO behavior violated");
    assert(obj6 == obj3 && "Free list LIFO behavior violated");
    std::cout << "   ✓ All assertions passed - LIFO behavior confirmed!\n";

    // Demonstrate allocation beyond preallocated capacity
    std::cout << "\n5. Testing allocation beyond preallocated capacity:\n";
    std::vector<int*> extra_objects;

    // Allocate all remaining preallocated blocks
    for(size_t i = 0; i < element_count - 3; ++i) {
        extra_objects.push_back(allocator.allocate(i + 7));
    }

    std::cout << "   Allocated " << (element_count - 3) << " more objects\n";
    std::cout << "   Total allocated: " << (3 + element_count - 3) << " objects\n";

    // Try one more allocation - this should use system allocator
    std::cout << "   Attempting one more allocation (beyond capacity)...\n";
    int* overflow_obj = allocator.allocate(100);
    std::cout << "   Overflow object allocated at: " << overflow_obj << "\n";
    std::cout << "   ✓ System allocator fallback working\n";

    // Clean up
    allocator.deallocate(obj4);
    allocator.deallocate(obj5);
    allocator.deallocate(obj6);
    allocator.deallocate(overflow_obj);

    for(auto obj : extra_objects) {
        allocator.deallocate(obj);
    }

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\n6. Debug statistics:\n";
    std::cout << "   Storage active count: " << allocator.storage_active_count << "\n";
    std::cout << "   New active count: " << allocator.new_active_count << "\n";
    std::cout << "   Active count: " << allocator.active_count << "\n";
    std::cout << "   Total allocations: " << allocator.total_allocs << "\n";
    std::cout << "   Total deallocations: " << allocator.total_deallocs << "\n";
    assert(allocator.active_count == 0 && "Memory leak detected!");
#endif

    std::cout << "\n=== Demonstration complete ===\n";
}

// Example usage
int main() {
    demonstrate_block_allocator_behavior<5>();  // Small capacity for demonstration
    return 0;
}
```

This demonstration shows:

1. **LIFO Behavior**: The free list works as a stack - last deallocated is first allocated
2. **Address Reuse**: Deallocated blocks are reused for new allocations
3. **System Allocator Fallback**: When preallocated blocks are exhausted, it falls back to `new`
4. **Memory Management**: Proper cleanup to avoid memory leaks

The key insight is that `deallocate()` internally calls `push()` to add blocks to the free list head, and `allocate()` calls `pop()` to remove from the head, creating the LIFO behavior we observe.

