    std::cout << "   Deallocating obj2 (" << obj2 << ") next\n";
    allocator.deallocate(obj2);

    std::cout << "   Deallocating obj1 (" << obj1 << ") last\n";
    allocator.deallocate(obj1);

    // Now allocate again - should get the same blocks but in reverse order
