    std::cout << "   obj4 (" << obj4 << ") should equal obj1's address\n";
    std::cout << "   obj5 (" << obj5 << ") should equal obj2's address\n";
    std::cout << "   obj6 (" << obj6 << ") should equal obj3's address\n";

    assert(obj4 == obj1 && "Free list LIFO behavior violated");
    assert(obj5 == obj2 && "Free list LIFO behavior violated");
    assert(obj6 == obj3 && "Free list LIFO behavior violated");
    std::cout << "   ✓ All assertions passed - LIFO behavior confirmed!\n";

