    std::cout << "   Total allocated: " << (3 + element_count - 3) << " objects\n";

    // Try one more allocation - this should use system allocator
    std::cout << "   Attempting one more allocation (beyond capacity)...\n";
    int* overflow_obj = allocator.allocate(100);
    std::cout << "   Overflow object allocated at: " << overflow_obj << "\n";
    std::cout << "   ✓ System allocator fallback working\n";

    // Clean up
    allocator.deallocate(obj4);
    allocator.deallocate(obj5);
    allocator.deallocate(obj6);
    allocator.deallocate(overflow_obj);

    for(auto obj : extra_objects) {
