	 */
	size_type read_max() const {
		if(read_limit_) {
			assert(total_read_ < read_limit_);
			return read_limit_ - total_read_;
		} else {
			return buffer_.size();
		}
	}

	/**
	 * @brief Determine whether the stream is in a usable state.
	 * 
