#ifdef HEXI_DEBUG_ALLOCATORS
		++total_deallocs;
		--active_allocs;
#endif
		allocator_handle()->deallocate(t);
	}

#ifdef HEXI_DEBUG_ALLOCATORS
	auto allocator() {
		initialise();
		return allocator_handle();
	}
#endif

	~tls_block_allocator() {
		thread_exit();

#ifdef HEXI_DEBUG_ALLOCATORS
		assert(active_allocs == 0);
#endif
	}
