std::vector<uint8_t> write_and_read_data(const std::vector<uint8_t>& input_data) {
    // Create a buffer to hold the data
    std::vector<uint8_t> buffer;

    // Use buffer_write_adaptor to write data
    hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>> write_adaptor(buffer, hexi::init_empty);

    // Check available space before writing
    if (write_adaptor.free() < input_data.size()) {
        // If not enough space, we can still write as the adaptor will handle resizing
        // The write() method will automatically resize if needed
