    // Write the data to the buffer
    write_adaptor.write(input_data.data(), input_data.size());

    // Now use buffer_read_adaptor to read it back
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> read_adaptor(buffer);

    // Check the readable size
    std::vector<uint8_t> result(read_adaptor.size());

    // Read the data back
    read_adaptor.read(result.data(), result.size());

    return result;
