    hexi::buffer_adaptor adaptor(temp_buffer);

    // Read until buffer is empty
    while (!adaptor.empty()) {
        // Check remaining data size
        std::size_t remaining = adaptor.size();

        // Determine how much to read in this chunk
        std::size_t read_size = (remaining < chunk_size) ? remaining : chunk_size;

        // Create temporary buffer for this chunk
